type StaticUnionPolicy struct {
	// NL→IR Item C1 Path A: the current event's typed `_event.data` payload,
	// lifted from the dequeued event by PopulateEventMetadata and read by the
	// native transition guards (`p.pending<Event>Payload.<field>`). Mirrors
	// the Rust policy's `pending_payload` / the C11 `sm->pending_payload`.
	pendingPayloadTag StaticUnionPayloadTag
	pendingShapeSaidPayload StaticUnionShapeSaidPayload
	pendingShapesSentPayload StaticUnionShapesSentPayload

	pendingEventData string
	// W3C SCXML 5.10: Session ID
	SessionID string
	// ── SCE Accepted Subset §2.15: the datamodel="sce-static" variables ──
	// W3C SCXML 5.2: the `built` datamodel variable, published (`sce:direction="out"`).
	vBuilt StaticUnionUnionShapeUnion
	// W3C SCXML 5.2: the `kept` datamodel variable, published (`sce:direction="out"`).
	vKept optional.Of[StaticUnionUnionShapeUnion]
	// W3C SCXML 5.2: the `last_kind` datamodel variable, published (`sce:direction="out"`).
	vLastKind StaticUnionKindEnum
	// W3C SCXML 5.2: the `radius` datamodel variable, published (`sce:direction="out"`).
	vRadius uint16
	// W3C SCXML 5.2: the `width` datamodel variable, published (`sce:direction="out"`).
	vWidth uint16
	// W3C SCXML 5.2: the `height` datamodel variable, published (`sce:direction="out"`).
	vHeight uint16
	// W3C SCXML 5.2: the `labels` datamodel variable, published (`sce:direction="out"`).
	vLabels uint32
	// W3C SCXML 5.2: the `points` datamodel variable, published (`sce:direction="out"`).
	vPoints uint32
	// W3C SCXML 5.2: the `dots` datamodel variable, published (`sce:direction="out"`).
	vDots uint32
	// W3C SCXML 5.2: the `many_radius` datamodel variable, published (`sce:direction="out"`).
	vManyRadius uint16
	// W3C SCXML 5.2: the `many_width` datamodel variable, published (`sce:direction="out"`).
	vManyWidth uint16
	// W3C SCXML 5.2: the `many_shapes` datamodel variable, published (`sce:direction="out"`).
	vManyShapes uint32
	// W3C SCXML 5.2: the `maybe_width` datamodel variable, published (`sce:direction="out"`).
	vMaybeWidth uint16
	// W3C SCXML 5.2: the `refusals` datamodel variable, published (`sce:direction="out"`).
	vRefusals uint32
	// W3C SCXML 5.2: the `lifted` datamodel variable, published (`sce:direction="out"`).
	vLifted optional.Of[StaticUnionUnionShapeUnion]
	// W3C SCXML 5.2: the `lift_why` datamodel variable, published (`sce:direction="out"`).
	vLiftWhy optional.Of[StaticUnionLiftRefusalRecord]
	// W3C SCXML 6.4: Parent communication (unbounded — see sce.ParentEventQueue)
	ParentExternalQueue *sce.ParentEventQueue
	InvokeID           string
	ChildSessionID     string
	// W3C SCXML C.1: the id of the session that invoked this one, whose
	// published location reaches it as `#_parent` does (docs/adr/0090); empty
	// for a session its host started.
	ParentSessionID    string
	// §scxml-6.4.3: invoke param VALUES staged by the parent, applied after
	// this machine's datamodel init so they override its `<data>` defaults.
	pendingParams      map[string]interface{}
}

// NewStaticUnionPolicy creates a new policy with default values.
func NewStaticUnionPolicy() StaticUnionPolicy {
	return StaticUnionPolicy{
		// docs/adr/0045: a session has an id, which a saved state names it by and
		// a peer addresses it by. A host that has one for it gives it with
		// SetSessionID before it starts the machine; a child's is its parent's
		// and the id it was started under.
		SessionID: sce.DrawSessionID(),
		vBuilt: StaticUnionUnionShapeUnionRect(StaticUnionRectRecord{width: 1, height: 2}),
		vKept: optional.None[StaticUnionUnionShapeUnion](),
		vLastKind: StaticUnionKindEnumDot,
		vRadius: 0,
		vWidth: 0,
		vHeight: 0,
		vLabels: 0,
		vPoints: 0,
		vDots: 0,
		vManyRadius: 0,
		vManyWidth: 0,
		vManyShapes: 0,
		vMaybeWidth: 0,
		vRefusals: 0,
		vLifted: optional.None[StaticUnionUnionShapeUnion](),
		vLiftWhy: optional.None[StaticUnionLiftRefusalRecord](),
	}
}

// SetSessionID gives this session the id its host has for it, in place of the
// one it drew: an XML Nmtoken, since another session addresses this one as
// `#_scxml_<id>` and every child's id is this one's and the id the child was
// started under (docs/adr/0045). Refused for anything else. Called before the
// machine starts, since what it sends names it by the id it began with.
// Declared whether or not a saved state can hold the machine: a root's id is
// bound when the machine is created, whether or not it saves.
func (p *StaticUnionPolicy) SetSessionID(id string) error {
	if reason := sce.SessionIDRefusalOf(id); reason != "" {
		return sce.Refuse(reason)
	}
	p.SessionID = id
	return nil
}

